/**
 * Available avatar sizes that affect initial display logic
 */
export type AvatarSize = 'xsmall' | 'small' | 'medium' | 'large';
/**
 * Props for the AvatarInitials component
 */
export interface AvatarInitialsProps {
    /** User name to generate initials from */
    userName: string;
    /** Additional CSS classes */
    className?: string;
    /** Avatar size affects how many initials are shown */
    size?: AvatarSize;
}
